<?php
namespace App\Services\Procurement;
use App\Models\{Account,GoodsReceivedNote,PurchaseOrder,PurchaseReturn,StockCount,StockTransfer,SupplierInvoice,SupplierPayment};use App\Services\Accounting\AccountingService;use Illuminate\Support\Facades\DB;use RuntimeException;
class ProcurementService{public function __construct(private StoreStockService $stock){}
 public function approveOrder(PurchaseOrder $po,int $userId):PurchaseOrder{if($po->status!=='draft')throw new RuntimeException('Only draft purchase orders can be approved.');$po->update(['status'=>'approved','approved_by'=>$userId,'approved_at'=>now()]);return $po;}
 public function postGrn(GoodsReceivedNote $grn,int $userId):GoodsReceivedNote{return DB::transaction(function()use($grn,$userId){$grn=GoodsReceivedNote::with(['items.inventoryItem','order.supplier','store'])->lockForUpdate()->findOrFail($grn->id);if($grn->status==='posted')return $grn;foreach($grn->items as $line){$net=max(0,(float)$line->quantity_received-(float)$line->quantity_rejected);if($net<=0)continue;$this->stock->receiveBatch($grn->store,$line->inventoryItem,$net,(float)$line->unit_cost,$line->batch_number,$line->expires_at,$grn->order->supplier_id,$grn,$userId,$grn->number);$poLine=$grn->order->items()->find($line->purchase_order_item_id);if($poLine)$poLine->increment('received_quantity',$net);}$grn->update(['status'=>'posted','posted_at'=>now()]);$grn->order->refresh();$remaining=$grn->order->items()->whereColumn('received_quantity','<','quantity')->exists();$grn->order->update(['status'=>$remaining?'part_received':'received']);return $grn;});}
 public function dispatchTransfer(StockTransfer $transfer,int $userId):StockTransfer{return DB::transaction(function()use($transfer,$userId){$transfer=StockTransfer::with(['items.inventoryItem','fromStore','toStore'])->lockForUpdate()->findOrFail($transfer->id);if(in_array($transfer->status,['dispatched','received'],true))return $transfer;foreach($transfer->items as $line){$qty=(float)($line->quantity_dispatched?:$line->quantity_requested);$this->stock->transfer($transfer->fromStore,$transfer->toStore,$line->inventoryItem,$qty,$userId,$transfer,$transfer->number);$line->update(['quantity_dispatched'=>$qty,'quantity_received'=>$qty]);}$transfer->update(['status'=>'received','approved_by'=>$userId,'received_by'=>$userId,'dispatched_at'=>now(),'received_at'=>now()]);return $transfer;});}
 public function postCount(StockCount $count,int $userId):StockCount{return DB::transaction(function()use($count,$userId){$count=StockCount::with(['items.inventoryItem','store'])->lockForUpdate()->findOrFail($count->id);if($count->status==='posted')return $count;foreach($count->items as $line){if($line->counted_quantity===null)continue;$variance=(float)$line->counted_quantity-(float)$line->system_quantity;if(abs($variance)>0.00001)$this->stock->move($count->store,$line->inventoryItem,$variance,'adjustment',$userId,'Physical stock count variance',$count,null,$count->number);$line->update(['variance_quantity'=>$variance]);}$count->update(['status'=>'posted','approved_by'=>$userId,'posted_at'=>now()]);return $count;});}
 public function postReturn(PurchaseReturn $return,int $userId):PurchaseReturn{return DB::transaction(function()use($return,$userId){$return=PurchaseReturn::with(['items.inventoryItem','store'])->lockForUpdate()->findOrFail($return->id);if($return->status==='posted')return $return;foreach($return->items as $line)$this->stock->move($return->store,$line->inventoryItem,-1*(float)$line->quantity,'return',$userId,'Return to supplier: '.$return->reason,$return,null,$return->number,(float)$line->unit_cost);$return->update(['status'=>'posted','posted_at'=>now()]);return $return;});}
 public function payInvoice(SupplierInvoice $invoice,array $data,int $userId):SupplierPayment{return DB::transaction(function()use($invoice,$data,$userId){$invoice=SupplierInvoice::lockForUpdate()->findOrFail($invoice->id);$balance=(float)$invoice->total_amount-(float)$invoice->paid_amount;$amount=(float)$data['amount'];if($amount<=0||$amount>$balance+0.01)throw new RuntimeException('Payment amount exceeds the supplier invoice balance.');$payment=SupplierPayment::create(['property_id'=>$invoice->property_id,'supplier_id'=>$invoice->supplier_id,'supplier_invoice_id'=>$invoice->id,'reference'=>$data['reference'],'payment_date'=>$data['payment_date'],'method'=>$data['method'],'amount'=>$amount,'external_reference'=>$data['external_reference']??null,'notes'=>$data['notes']??null,'created_by'=>$userId]);$paid=(float)$invoice->paid_amount+$amount;$invoice->update(['paid_amount'=>$paid,'status'=>$paid+0.01>=(float)$invoice->total_amount?'paid':'part_paid']);if(Account::where('property_id',$invoice->property_id)->where('code','2000')->exists()){$je=app(AccountingService::class)->postSupplierPayment($invoice->property_id,$payment->id,$payment->method,(float)$payment->amount,$userId);$payment->update(['journal_entry_id'=>$je->id]);}return $payment;});}
}
